modules/gpu/claim-mapper/main.tf: resource "redwood_tenant_lease" "mapped" {
  count = var.enable_claim_indexing ? length(var.tenant_claims) : 0
  tenant_id = var.tenant_claims[count.index].id
  az_affinity = var.tenant_claims[count.index].preferred_azs[0]
}
modules/iam/shard-bridge/roles.tpl: {{- /* minimal role granting node attach and read-only metadata used by tenant workloads */ -}}
resource "aws_iam_role" "tenant_role_{{ .TenantID }}" {
  name = "redwood-tenant-{{ .TenantID }}-role-{{ .Suffix }}"
}
